// HasProperty applies the HasEdge predicate on the "property" edge.
func HasProperty() predicate.PropertyUnitType {
	return predicate.PropertyUnitType(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, PropertyTable, PropertyColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasPropertyWith applies the HasEdge predicate on the "property" edge with a given conditions (other predicates).
func HasPropertyWith(preds ...predicate.Property) predicate.PropertyUnitType {
	return predicate.PropertyUnitType(func(s *sql.Selector) {
		step := newPropertyStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.PropertyUnitType) predicate.PropertyUnitType {
	return predicate.PropertyUnitType(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.PropertyUnitType) predicate.PropertyUnitType {
	return predicate.PropertyUnitType(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.PropertyUnitType) predicate.PropertyUnitType {
	return predicate.PropertyUnitType(sql.NotPredicates(p))
}
